select
a.device_id,
a.mete_id,
a.mete_name,
a.up_effect,
a.down_effect,
a.mete_precision,
a.unit,
a.mete_index,
a.mete_cid,
a.limit_band,
a.change_limit,
a.valid_mid,
a.valid_string,
a.invalid_value,
a.last_value,
a.last_time,
a.mete_code,
a.device_type,
a.description,
a.hilimit1,
a.lolimit1,
a.hilimit2,
a.lolimit2,
a.hilimit3,
a.lolimit3,
a.hilimit4,
a.lolimit4,
a.stander,
a.isshield,
a.storageperiod,
a.link_mete_id
from t_cfg_telemeter a
where 1 = 1
 and a.device_id = #{deviceId, jdbcType=VARCHAR}
 and a.mete_id = #{meteId, jdbcType=VARCHAR}
 and a.mete_name = #{meteName, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=REAL}
 and a.down_effect = #{downEffect, jdbcType=REAL}
 and a.mete_precision = #{metePrecision, jdbcType=INTEGER}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.mete_index = #{meteIndex, jdbcType=INTEGER}
 and a.mete_cid = #{meteCid, jdbcType=INTEGER}
 and a.limit_band = #{limitBand, jdbcType=REAL}
 and a.change_limit = #{changeLimit, jdbcType=REAL}
 and a.valid_mid = #{validMid, jdbcType=VARCHAR}
 and a.valid_string = #{validString, jdbcType=VARCHAR}
 and a.invalid_value = #{invalidValue, jdbcType=REAL}
 and a.last_value = #{lastValue, jdbcType=REAL}
 and a.last_time = #{lastTime, jdbcType=TIMESTAMP}
 and a.mete_code = #{meteCode, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=VARCHAR}
 and a.description = #{description, jdbcType=VARCHAR}
 and a.hilimit1 = #{hilimit1, jdbcType=REAL}
 and a.lolimit1 = #{lolimit1, jdbcType=REAL}
 and a.hilimit2 = #{hilimit2, jdbcType=REAL}
 and a.lolimit2 = #{lolimit2, jdbcType=REAL}
 and a.hilimit3 = #{hilimit3, jdbcType=REAL}
 and a.lolimit3 = #{lolimit3, jdbcType=REAL}
 and a.hilimit4 = #{hilimit4, jdbcType=REAL}
 and a.lolimit4 = #{lolimit4, jdbcType=REAL}
 and a.stander = #{stander, jdbcType=REAL}
 and a.isshield = #{isshield, jdbcType=INTEGER}
 and a.storageperiod = #{storageperiod, jdbcType=BIGINT}
 and a.link_mete_id = #{linkMeteId, jdbcType=VARCHAR}

